/** Put the sheet in the document once, before the first render. */
export function installChatWindowStyles(doc: Document = document): void {
  if (doc.getElementById(CHAT_WINDOW_STYLE_ID)) return
  const style = doc.createElement('style')
  style.id = CHAT_WINDOW_STYLE_ID
  style.textContent = CHAT_WINDOW_CSS
  doc.head.appendChild(style)
}
